-- modules: 9 行
INSERT OR REPLACE INTO modules (id, slug, name, description, author, category_id, version, source_id, source_path, content_hash, upstream_url, repository_url, is_featured, is_published, published_at, synced_at, created_at, updated_at, deleted_at, review_status, sort_weight) VALUES ('mod-dns-lite', 'dns-lite', 'DNS Lite', 'V1.0 国内/国外双 DNS 智能分流 + 广告与追踪域名拦截。国内域名走国内 DNS，其余走国外加密 DNS。', '许舟', 'cat-rules', '1.0', 'src-zhiaon-modules', 'dnslite.sgmodule', 'a4e1c6a05af7', NULL, NULL, 0, 1, '2026-11-08T10:36:16Z', '2026-11-08T10:36:16Z', '2026-11-08T10:36:16Z', '2026-11-08T10:36:33Z', NULL, 'approved', 0);
INSERT OR REPLACE INTO modules (id, slug, name, description, author, category_id, version, source_id, source_path, content_hash, upstream_url, repository_url, is_featured, is_published, published_at, synced_at, created_at, updated_at, deleted_at, review_status, sort_weight) VALUES ('mod-dns', 'dns', 'DNS 清理缓存', 'V1.0 一键刷新 Surge DNS 缓存。卡片显示缓存条目数与上次刷新时间，点刷新按钮才执行 POST /v1/dns/flush，随后回读缓存条数核对，成功/未生效/失败都如实显示，不伪造状态。', '许舟', 'cat-rules', '1.0', 'src-zhiaon-modules', 'dnsrefresh.sgmodule', 'b6f1232f95fa', NULL, NULL, 0, 1, '2026-11-08T10:36:34Z', '2026-11-08T10:36:34Z', '2026-11-08T10:36:34Z', '2026-11-08T10:36:34Z', NULL, 'approved', 0);
INSERT OR REPLACE INTO modules (id, slug, name, description, author, category_id, version, source_id, source_path, content_hash, upstream_url, repository_url, is_featured, is_published, published_at, synced_at, created_at, updated_at, deleted_at, review_status, sort_weight) VALUES ('mod-fanqie', 'fanqie', '番茄小说去广告', '新增 lf-fe*.fqnovelstatic.com 拦截 —— 实测「番茄送你惊喜电商券」运营弹窗弹出瞬间拉 1.1 MB 活动页前端包；V1.23 基础：摘除失效的 [Script] 段（番茄证书固定，fanqie_clean.js 永远跑不起来，纯占位误导）；V1.22 基础：撤回 pddpic 拦截（会误伤拼多多App图片），活动卡改靠接口断供，仅做 SNI/域名层拦截', '许舟', 'cat-adblock', '1.24', 'src-zhiaon-modules', 'fanqie.sgmodule', '648c01c719df', NULL, NULL, 0, 1, '2026-11-08T10:36:34Z', '2026-11-08T10:36:34Z', '2026-11-08T10:36:34Z', '2026-11-08T10:36:34Z', NULL, 'approved', 0);
INSERT OR REPLACE INTO modules (id, slug, name, description, author, category_id, version, source_id, source_path, content_hash, upstream_url, repository_url, is_featured, is_published, published_at, synced_at, created_at, updated_at, deleted_at, review_status, sort_weight) VALUES ('mod-hongguo', 'hongguo', '红果短剧去广告', 'V1.0 纯域名层去广告：穿山甲/Pangle 广告 SDK 全族、红果广告视频子域 v*-reading-ad、广告素材签名（-ad-sign / mgsd-sign / luckycat）、广告位调度 TNC、小游戏与电商推广位、埋点上报、直播带货卡片信令。正片 CDN 与图床全部前置放行，不需要 MITM 与证书。', '许舟', 'cat-adblock', '1.0', 'src-zhiaon-modules', 'hongguo.sgmodule', '7d871e52a362', NULL, NULL, 0, 1, '2026-11-08T10:36:35Z', '2026-11-08T10:36:35Z', '2026-11-08T10:36:35Z', '2026-11-08T10:36:35Z', NULL, 'approved', 0);
INSERT OR REPLACE INTO modules (id, slug, name, description, author, category_id, version, source_id, source_path, content_hash, upstream_url, repository_url, is_featured, is_published, published_at, synced_at, created_at, updated_at, deleted_at, review_status, sort_weight) VALUES ('mod-ipinfo', 'ipinfo', '网络IP信息', 'V1.2 显示当前网络的 IP 全链路：本机公网 IP、各策略组的真实入口 IP 与节点落地 IP，均含位置和运营商。兜底组常驻，不受参数影响。首行显示 Wi-Fi 名，蜂窝下显示「蜂窝流量」。', '许舟', 'cat-tools', '1.2', 'src-zhiaon-modules', 'ipinfo.sgmodule', '91560096a15f', NULL, NULL, 0, 1, '2026-11-08T10:36:36Z', '2026-11-08T10:36:36Z', '2026-11-08T10:36:36Z', '2026-11-08T10:36:36Z', NULL, 'approved', 0);
INSERT OR REPLACE INTO modules (id, slug, name, description, author, category_id, version, source_id, source_path, content_hash, upstream_url, repository_url, is_featured, is_published, published_at, synced_at, created_at, updated_at, deleted_at, review_status, sort_weight) VALUES ('mod-jichang', 'jichang', '机场流量', '复制订阅链接进去就可以了。重置日留空则该机场不显示重置信息。', '许舟', 'cat-tools', '1.1', 'src-zhiaon-modules', 'jichang.sgmodule', '93b5139f8696', NULL, NULL, 0, 1, '2026-11-08T10:36:36Z', '2026-11-08T10:36:36Z', '2026-11-08T10:36:36Z', '2026-11-08T10:36:36Z', NULL, 'approved', 0);
INSERT OR REPLACE INTO modules (id, slug, name, description, author, category_id, version, source_id, source_path, content_hash, upstream_url, repository_url, is_featured, is_published, published_at, synced_at, created_at, updated_at, deleted_at, review_status, sort_weight) VALUES ('mod-qimao', 'qimao', '七猫小说去广告', '补 hc-ssp.sm.cn、ai.advertisement.alibabacorp.sm.cn、reachmax.cn', '许舟', 'cat-adblock', '1.1.5', 'src-zhiaon-modules', 'qimao.sgmodule', 'f6ac1b2cdf3b', NULL, NULL, 0, 1, '2026-11-08T10:36:37Z', '2026-11-08T10:36:37Z', '2026-11-08T10:36:37Z', '2026-11-08T10:36:37Z', NULL, 'approved', 0);
INSERT OR REPLACE INTO modules (id, slug, name, description, author, category_id, version, source_id, source_path, content_hash, upstream_url, repository_url, is_featured, is_published, published_at, synced_at, created_at, updated_at, deleted_at, review_status, sort_weight) VALUES ('mod-streaming', 'streaming', '流媒体解锁', 'V1.3 逐平台实测解锁状态：Netflix、Disney+、YouTube、Prime Video、Spotify、HBO Max、Hulu、Paramount+、Peacock、Viu、Abema、巴哈动画疯、B站港澳台，以及 ChatGPT / Claude / Gemini 三家人工智能服务。每个策略组一块，发真实请求看对方真正看到的地区，不靠 IP 库猜。V1.3 改为图标打头排版，任何机型、任何字号下勾叉列都不会再错位。', '许舟', 'cat-tools', '1.3', 'src-zhiaon-modules', 'streaming.sgmodule', '44d89b5562d7', NULL, NULL, 0, 1, '2026-11-08T10:36:38Z', '2026-11-08T10:36:38Z', '2026-11-08T10:36:38Z', '2026-11-08T10:36:38Z', NULL, 'approved', 0);

